function trasforma(input){
  var tot = parseFloat(String(input.Totale).replace(/€|\s/g, '').replace(/\./g, '').replace(',', '.'));
  var a = /esente/i.test(input.AliquotaIVA) ? 0 : parseFloat(String(input.AliquotaIVA).replace(/[^0-9,.]/g, '').replace(',', '.'));
  var imp = Math.round(tot / (1 + a / 100) * 100) / 100;
  return { imponibile: imp, iva: Math.round((tot - imp) * 100) / 100 };
}
